<?php get_header(); ?><section class="wrap intro"><p class="eyebrow">An editorial home</p><h1><?php echo esc_html(get_bloginfo('name')); ?></h1><p><?php echo esc_html(get_bloginfo('description')); ?></p></section><section class="wrap"><h2>Latest writing</h2><div class="post-grid"><?php $latest=new WP_Query(['posts_per_page'=>6]);while($latest->have_posts()):$latest->the_post(); ?><article class="post-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large'); ?><h3><?php the_title(); ?></h3></a><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),24)); ?></p></article><?php endwhile;wp_reset_postdata(); ?></div></section><?php get_footer(); ?>